    CONSTRAINT CK_Consent_Type CHECK (ConsentType IN ('MARKETING_EMAIL','SMS','TERMS','PRIVACY')),
    CONSTRAINT CK_Consent_Source CHECK (Source IN ('WEB','MAUI','JOTFORM_IMPORT','SADMIN'))
);
END
