    UpdatedAt    DATETIME2(3)   NOT NULL CONSTRAINT DF_StaticPage_UpdatedAt DEFAULT SYSUTCDATETIME(),
    CONSTRAINT UQ_StaticPage_Slug UNIQUE (Slug),
    CONSTRAINT UQ_StaticPage_Loc UNIQUE (LocPath)
);
