SELECT 'CALENDAR_FEATURED', e.ShopEventId, 'FEATURED', 2.00, 0, @Now, DATEADD(day, 45, e.StartsAt)
FROM mkt.ShopEvent e WHERE e.Slug = N'collect-a-con-houston-2026-11';


