SET NOCOUNT ON;
SET XACT_ABORT ON;
GO
DECLARE @Now DATETIME2(3) = SYSUTCDATETIME();


MERGE core.MediaAsset AS t
USING (SELECT N'legacy/assets/graded-slabs.jpeg' AS ObjectKey) AS s
ON t.ObjectKey = s.ObjectKey
WHEN MATCHED THEN UPDATE SET
    LegacyPath = N'assets/graded-slabs.jpeg',
    Visibility = 'PUBLIC',
    Status = 'READY',
    ContentType = 'image/jpeg',
    AltText = N'Stacks of graded cards',
    UpdatedAt = @Now
WHEN NOT MATCHED THEN INSERT
    (ObjectKey, LegacyPath, Visibility, ContentType, Status, AltText)
VALUES
    (N'legacy/assets/graded-slabs.jpeg', N'assets/graded-slabs.jpeg', 'PUBLIC', 'image/jpeg', 'READY', N'Stacks of graded cards');

MERGE cms.GalleryItem AS t
USING (SELECT N'graded-slabs' AS Slug) AS s
ON t.Slug = s.Slug
WHEN MATCHED THEN UPDATE SET
    Caption = N'Graded collections',
    AltText = N'Stacks of graded cards',
    LegacyPath = N'assets/graded-slabs.jpeg',
    MediaAssetId = (SELECT MediaAssetId FROM core.MediaAsset WHERE ObjectKey = N'legacy/assets/graded-slabs.jpeg'),
    DisplayOrder = 10,
    IsPublished = 1,
    UpdatedAt = @Now
WHEN NOT MATCHED THEN INSERT
    (Slug, Caption, AltText, LegacyPath, MediaAssetId, DisplayOrder, IsPublished)
VALUES
    (N'graded-slabs', N'Graded collections', N'Stacks of graded cards', N'assets/graded-slabs.jpeg',
     (SELECT MediaAssetId FROM core.MediaAsset WHERE ObjectKey = N'legacy/assets/graded-slabs.jpeg'), 10, 1);


